parameters.jsCode:
// target_node_id was resolved upstream, by Agent: Find (agent-intent-finder.json), from
// the raw intention_nodes object already on the item -- this flow only ever reads that
// resolution, it never re-resolves which node the user means itself (see Router-dispatched
// flows assuming resolved context, the same convention every other route follows).
//
// business_partner_ref is read straight off the target, not asked of the user -- CardCode is
// SAP B1's own established field name for a Business Partner code (see e.g.
// sap-process-form-filling.json's own reference to it).
//
// document_type/document_mapping are entity-level facts, declared on the process's own
// referenced *schema*, not on any one CRUD operation over it (a customer's invoice-generation
// capability should apply the same way whether the node came from a get, a list, or a future
// create) -- schema-resolution.json's Decode & Set Schema merges the schema in as a NESTED
// process_definition.schema_definition key (not spread onto the top level), so that is read
// first; a top-level process_definition.document_type/document_mapping still wins when an
// operation file declares its own override. Absent entirely means '' / null here, which
// Django's /api/v1/document/generate/ already rejects cleanly as UNSUPPORTED_DOCUMENT_TYPE
// (see Handle Render Result's friendlier message for that case).
const data = $json;
const nodes = data.intention_nodes || {};
// A first-time generate_document request carries target_node_id (Agent: Find's STEP 2
// resolution, same as new_intent's own target resolution). A confirming_document
// RESUMPTION never sets target_node_id -- Agent: Find's output for that status is just
// {"status": "confirming_document"} -- it relies on active_node_id already pointing at the
// node, same convention pending_reply uses and the same one Compute Route Key's own
// confirming_document check already reads. Falling back to active_node_id here closes that
// gap -- confirmed live: without it, every confirming_document resumption hit "No Target
// Found" even though classification and routing were both already correct.
const targetNodeId = data.target_node_id || data.active_node_id;
const target = targetNodeId ? nodes[targetNodeId] : null;
const formState = target?.form_state || null;
const processDefinition = target?.process_definition || {};
const schemaDefinition = processDefinition.schema_definition || {};
const documentType = schemaDefinition.document_type || processDefinition.document_type || '';
const documentMapping = schemaDefinition.document_mapping || processDefinition.document_mapping || null;
return [{ json: {
  ...data,
  target_node_id: targetNodeId,
  _target_document_type: documentType,
  _target_document_mapping: documentMapping,
  _target_form_state: formState,
  _target_business_partner_ref: formState?.CardCode || '',
  _target_status: target?.status || '',
  _target_found: Boolean(target),
} }];

// Generic, document-type-agnostic field mapper: reads the target process's own declared
// document_mapping (schema-level -- see Resolve Target Node) and applies it mechanically to
// the target's form_state, using the (possibly edited) working copy of line items from a
// just-finished customization loop when one ran. No SAP-field-name literals live in this node
// -- a different customer's own template/mapping needs only their own schema override, never
// a workflow change.
const data = $json;
const form = data._target_form_state || {};
const mapping = data._target_document_mapping || {};

const headerFields = mapping.header_fields || {};
const headerTransforms = mapping.header_transforms || {};
const constants = mapping.constants || {};
const constantsFromFields = mapping.constants_from_fields || {};
const lineItemFields = mapping.line_item_fields || {};
const lineItemSource = mapping.line_item_source || '';
const paramsSpec = mapping.params || {};

// SAP text fields (e.g. Address) can carry bare \r line separators -- confirmed live these
// render as an invisible/blank glyph instead of a real line break (the renderer's text
// layout only recognizes \n). Normalizing here, once, covers every mapped field uniformly
// rather than special-casing Address.
const normalizeText = (value) => (typeof value === 'string' ? value.replace(/\r\n/g, '\n').replace(/\r/g, '\n') : value);

const assign = (row, targets, value) => {
  const normalized = normalizeText(value);
  const list = Array.isArray(targets) ? targets : [targets];
  for (const key of list) row[key] = normalized;
};

// Some header data only exists on an expanded related entity (e.g. the customer's own CUIT
// lives on BusinessPartner, not on the invoice itself, reached via a live $expand=BusinessPartner
// -- confirmed live) -- a dotted sapField ("BusinessPartner.FederalTaxID") walks into that
// nested object; a plain field name still does a single, direct lookup exactly as before, so
// this is a strict superset of the old behavior, not a breaking change.
const getPath = (obj, path) => path.split('.').reduce((acc, key) => (acc == null ? acc : acc[key]), obj);

const headerRow = { ...constants };
for (const [sapField, targets] of Object.entries(headerFields)) {
  assign(headerRow, targets, getPath(form, sapField) ?? null);
}
for (const transform of Object.values(headerTransforms)) {
  const raw = getPath(form, transform.source);
  const mapped = (transform.lookup || {})[raw];
  assign(headerRow, transform.target, mapped ?? transform.default ?? null);
}
for (const [constantField, sourceField] of Object.entries(constantsFromFields)) {
  headerRow[constantField] = normalizeText(getPath(form, sourceField) ?? null);
}
// Some report fields are arithmetic over two SAP fields (e.g. a printed SubTotal that SAP's
// own Crystal integration would normally inject, but we supply our own dataset) -- header_fields/
// constants/constants_from_fields are all direct-passthrough-or-fixed, so this is the one
// mapping primitive that computes a value instead of just relocating or fixing one.
const computedFields = mapping.computed_fields || {};
for (const [targetField, spec] of Object.entries(computedFields)) {
  if (spec.op === 'subtract') {
    assign(headerRow, targetField, (Number(getPath(form, spec.a)) || 0) - (Number(getPath(form, spec.b)) || 0));
  }
}

// Set only by Merge QR Result, gated on Needs QR?/mapping.qr_source -- absent for any
// document type that doesn't declare qr_source, unchanged from today's behavior.
if (mapping.qr_source && data._qr_value != null) {
  headerRow[mapping.qr_source.target_field] = data._qr_value;
}

// The template's own embedded-logo picture (a BlobField bound to {OADP.LogoImage},
// confirmed live via rpt-rs's json-dump) reads from this MAIN row -- set by Merge Company
// Info Result from the organization's own company_info, never from SAP (no logo image
// data exists there at all). Distinct from -- and never confused with -- SREncabDocum's
// own separate, unrelated LogoImage field (subreport_constants/company_info_source both
// leave that one alone).
if (mapping.logo_source && data._logo_value != null) {
  headerRow[mapping.logo_source.target_field] = data._logo_value;
}

const targetNode = (data.intention_nodes || {})[data.target_node_id] || {};
const lineItems = targetNode._pending_document_lines
  || (lineItemSource ? form[lineItemSource] : null)
  || [];

let rows;
if (lineItemSource && lineItems.length) {
  rows = lineItems.map((line, index) => {
    const row = { ...headerRow, LineNum: index };
    for (const [sapField, targets] of Object.entries(lineItemFields)) {
      assign(row, targets, line[sapField] ?? null);
    }
    return row;
  });
} else {
  rows = [headerRow];
}

// A "source" param reads from headerRow (the already-mapped, already-fetched entity),
// never raw form_state -- confirmed live (2026-09-20) that form_state only ever holds
// whatever key the user actually supplied to resolve this record (e.g. DocNum for a
// lookup-by-number), not the entity's own DocEntry the way header_fields' own mapping of
// the fetched entity does. dockey@ in particular feeds the .rpt's own record-selection
// formula -- sourcing it from form_state silently filtered out every row (dockey@ resolved
// null/mismatched), rendering a fully blank body with no error, since nothing else in this
// pipeline treats "zero rows matched" as a failure.
const params = {};
for (const [paramName, spec] of Object.entries(paramsSpec)) {
  if ('source' in spec) params[paramName] = getPath(headerRow, spec.source) ?? null;
  else if ('constant' in spec) params[paramName] = spec.constant;
}

// Company-letterhead-style subreports (logo, phone, email, etc.) are invoice-independent --
// one fixed row per subreport, sourced entirely from the schema's own constants. A subreport
// gets its OWN independent dataset -- fields already present on the main row (e.g. CompnyName)
// are NOT automatically visible to it, so the schema must repeat whatever this specific
// subreport needs. (SREncabDocum specifically has moved to company_info_source below -- SAP
// does expose some of it live via SQLQueries, unlike the rest of this mechanism's assumption.)
const subreportConstants = mapping.subreport_constants || {};
const subreports = {};
for (const [subreportName, row] of Object.entries(subreportConstants)) {
  subreports[subreportName] = { rows: [row] };
}

// Company info (SREncabDocum): computed pre-call by Build/Merge Company Info Result --
// SAP-sourced where declared, Organization-sourced fallback/override otherwise (this
// instance's own OADM.CompnyName carries a test-environment prefix unusable for print;
// OADM has no website column at all) -- see Needs Company Info?/company_info_source.
if (mapping.company_info_source && data._company_info) {
  subreports[mapping.company_info_source.subreport] = { rows: [data._company_info] };
}

// TaxDetails.rpt: one row per VAT rate actually used by the lines being invoiced -- the same
// `lineItems` already resolved above (reflects any customization, not stale SAP data).
// Gated on tax_details_condition_field (e.g. VatSum) being non-zero -- no VAT, nothing to
// break down, matching subreport_constants' own no-op-when-absent convention.
const taxDetailsSpec = mapping.tax_details_source;
const conditionField = mapping.tax_details_condition_field;
if (taxDetailsSpec && (!conditionField || Number(getPath(headerRow, conditionField)) !== 0)) {
  const groups = new Map();
  for (const line of lineItems) {
    const rate = line[taxDetailsSpec.rate_field];
    const key = String(rate);
    const group = groups.get(key) || { rate, base: 0, tax: 0 };
    group.base += Number(line[taxDetailsSpec.base_field]) || 0;
    group.tax += Number(line[taxDetailsSpec.tax_field]) || 0;
    groups.set(key, group);
  }
  subreports[taxDetailsSpec.subreport] = {
    rows: [...groups.values()].map((group) => ({
      [taxDetailsSpec.dockey_field]: headerRow[taxDetailsSpec.dockey_field],
      CODE: `${taxDetailsSpec.code_prefix}${group.rate}`,
      RATE: group.rate,
      BASE: group.base,
      BASEME: group.base,
      TAX: group.tax,
      TAXME: group.tax,
      ORIGEN: '',
    })),
  };
}

// WTInPayment: one row per non-zero withholding entry, sourced from the ORIGINAL entity
// (document-level, unrelated to line-item customization) -- only non-zero amounts produce a
// row, so a document with no real withholding ends up with this subreport entirely absent,
// same as an empty tax-details table would be.
const wtSpec = mapping.withholding_source;
if (wtSpec) {
  const wtLines = (getPath(form, wtSpec.line_source) || []).filter(
    (line) => Number(line[wtSpec.amount_field]) !== 0
  );
  if (wtLines.length) {
    subreports[wtSpec.subreport] = {
      rows: wtLines.map((line) => {
        const row = { [wtSpec.dockey_target]: headerRow[wtSpec.dockey_field] };
        for (const [target, sourceField] of Object.entries(wtSpec.fields)) row[target] = line[sourceField];
        return row;
      }),
    };
  }
}

// A caller-supplied, per-organization override: force a specific named report section or
// object visible or hidden regardless of what the .rpt file's own static suppress flag or
// Object_Visibility/Section_Visibility formula would otherwise decide -- for sections some
// SAP B1 templates ship with a plain hard-coded suppress and no condition at all (e.g. an
// optional invoice-total line), which no amount of row/param data could ever influence.
// Sparse by design -- a section/object name absent from either map defers entirely to the
// template's own behavior, same as every org that doesn't declare this key at all.
//
// Both maps declare entries as {"param": "<params@ key>", "negate": <bool, optional>} rather
// than a literal boolean -- the renderer itself has no notion of this indirection (it parses
// section_visibility/object_visibility as plain {"Name": true/false} maps, see
// app/renderer/src/main.rs's build_section_visibility/build_object_visibility), so it must be
// resolved here, against the params@ flags computed above, before crossing that boundary.
// Confirmed live against docs/mockups_flags/*.json (this repo's own record of a proven-working
// render): section_visibility always emits its resolved value, true or false, directly --
// both states are meaningful, since it toggles a conditional section on or off outright.
// object_visibility only ever emits false (an explicit force-hide) -- a resolution of true is
// omitted entirely rather than sent, since every current use of it is suppressing a fallback
// object when its alternative is shown, never the reverse; the template's own default already
// leaves these objects visible absent an override.
const resolveFlag = (spec) => {
  const value = params[spec.param];
  return spec.negate ? !value : value;
};
const sectionVisibilitySpec = mapping.section_visibility || {};
const resolvedSectionVisibility = {};
for (const [sectionName, spec] of Object.entries(sectionVisibilitySpec)) {
  resolvedSectionVisibility[sectionName] = resolveFlag(spec);
}
const objectVisibilitySpec = mapping.object_visibility || {};
const resolvedObjectVisibility = {};
for (const [objectName, spec] of Object.entries(objectVisibilitySpec)) {
  if (resolveFlag(spec) === false) resolvedObjectVisibility[objectName] = false;
}

// params@ flags that exist only to drive the visibility resolution above (e.g.
// ShowEmbeddedLogo@) are never themselves real Crystal Reports parameters -- confirmed live
// or the exact same docs/mockups_flags/*.json record, whose own _params never carries them,
// only dockey@/objectid@/extparam@. Sending them anyway hasn't been confirmed harmless, so
// they're stripped here rather than assumed inert.
const visibilityOnlyParamNames = new Set([
  ...Object.values(sectionVisibilitySpec).map((spec) => spec.param),
  ...Object.values(objectVisibilitySpec).map((spec) => spec.param),
]);
const finalParams = Object.fromEntries(
  Object.entries(params).filter(([paramName]) => !visibilityOnlyParamNames.has(paramName))
);

return [{ json: { ...data, _rows: rows, _params: finalParams, _subreports: subreports, _section_visibility: resolvedSectionVisibility, _object_visibility: resolvedObjectVisibility } }];

const data = $('Resolve Target Node').first().json;
const response = $json;
const status = response.statusCode;
const body = response.body || {};
if (status === 201 || status === 409) {
  const already = status === 409;
  const MESSAGES = {
    es: already
      ? 'Ya había una versión generada antes -- pedime una versión nueva si la necesitás actualizada.'
      : 'Acá tenés el documento.',
    en: already
      ? "A version was already generated earlier -- ask me for a new version if you need it updated."
      : 'Here is the document.',
  };
  const lang = data.language || 'es';
  return [{ json: { ...data, message: MESSAGES[lang] || MESSAGES.es, attachment: { id: body.id, name: body.name }, error: null } }];
}
// Distinct from a genuine render failure -- this process's document_type is empty or has no
// template/system-fallback configured for it (see document/constants.py's SUPPORTED_DOCUMENT_TYPES),
// not something retrying will fix.
if (status === 400 && body.error === 'UNSUPPORTED_DOCUMENT_TYPE') {
  const UNSUPPORTED_MESSAGES = {
    es: 'Todavía no tengo un formato de documento configurado para este tipo de proceso.',
    en: "I don't have a document format configured for this type of process yet.",
  };
  const lang = data.language || 'es';
  return [{ json: { ...data, message: UNSUPPORTED_MESSAGES[lang] || UNSUPPORTED_MESSAGES.es, error: 'UNSUPPORTED_DOCUMENT_TYPE' } }];
}
const ERROR_MESSAGES = {
  es: 'No pude generar el documento. Probá de nuevo en un momento.',
  en: "I couldn't generate the document. Try again in a moment.",
};
const lang = data.language || 'es';
return [{ json: { ...data, message: ERROR_MESSAGES[lang] || ERROR_MESSAGES.es, error: 'RENDER_FAILED' } }];

const data = $json;
const MESSAGES = {
  es: 'No encontré a qué proceso te referís para generar el documento. ¿Podés indicarme cuál?',
  en: "I couldn't find which process you mean to generate a document for. Could you point me to it?",
};
const lang = data.language || 'es';
return [{ json: { ...data, message: MESSAGES[lang] || MESSAGES.es, error: 'NOT_FOUND' } }];

// First time generate_document reaches a target whose document_mapping opts into line-item
// customization: present the current line items and ask whether to add/remove/update any
// before generating, mirroring sap-process-form-filling.json's own turn-based pending-state
// convention -- but as a NEW, parallel status (confirming_document) rather than reusing
// pending_reply, which is tightly coupled to form-filling specifically (Compute Route Key in
// agent-intent-finder.json hardcodes pending_reply -> sap_form_filling and warns its
// TERMINAL_STATUSES/resume-walk logic must stay in sync across six files -- a new status
// avoids touching that).
const data = $json;
const mapping = data._target_document_mapping || {};
const form = data._target_form_state || {};
const lineItemSource = mapping.line_item_source || '';
const lines = lineItemSource ? (form[lineItemSource] || []) : [];

// The raw SAP line item can carry 100+ fields (e.g. a real Invoice DocumentLine) --
// dumping the whole object would be an unreadable wall of JSON for a chat message. Only
// the fields the schema itself declared meaningful (line_item_fields' own SAP-field keys)
// are shown, keeping this generic across document types instead of hardcoding field names.
const summaryFields = Object.keys(mapping.line_item_fields || {});
const summarizeLine = (line) => {
  if (!summaryFields.length) return JSON.stringify(line);
  const picked = {};
  for (const key of summaryFields) if (key in line) picked[key] = line[key];
  return JSON.stringify(picked);
};
const summarize = (items) => items.length
  ? items.map((line, i) => `${i + 1}. ${summarizeLine(line)}`).join('\n')
  : '(sin items)';

const MESSAGES = {
  es: `Antes de generar el documento, este es el detalle actual:\n${summarize(lines)}\n\n¿Querés agregar, quitar, o modificar algún ítem? Si no, decime que lo genere tal cual está.`,
  en: `Before generating the document, here is the current detail:\n${summarize(lines)}\n\nWould you like to add, remove, or update any items? If not, just tell me to generate it as-is.`,
};
const lang = data.language || 'es';

const nodeId = data.target_node_id;
const targetNode = data.intention_nodes[nodeId];
const intentionNodes = {
  ...data.intention_nodes,
  [nodeId]: { ...targetNode, status: 'confirming_document', _pre_confirmation_status: targetNode.status, _pending_document_lines: lines },
};

return [{ json: {
  ...data,
  intention_nodes: intentionNodes,
  active_node_id: nodeId,
  message: MESSAGES[lang] || MESSAGES.es,
  error: null,
} }];

const data = $json;
const target = data.intention_nodes[data.target_node_id] || {};
const lines = target._pending_document_lines || [];
const chatInput = `The user is reviewing a document's line items before it gets generated. Current line items (a JSON array, in order):
${JSON.stringify(lines, null, 2)}

The user's latest message: "${data.message}"

Respond in: ${data.language || 'es'}.`;
return [{ json: { ...data, chatInput } }];

const data = $json;
const nodeId = data.target_node_id;
const targetNode = data.intention_nodes[nodeId];
const lang = data.language || 'es';

const FAILURE_MESSAGES = {
  es: 'No pude procesar ese cambio. ¿Podés repetirlo de otra forma?',
  en: "I couldn't process that change. Could you rephrase it?",
};

let parsed = null;
if (!data.error && typeof data.output === 'string') {
  try { parsed = JSON.parse(data.output); } catch (e) { parsed = null; }
}

if (!parsed || !Array.isArray(parsed.lines)) {
  const intentionNodes = {
    ...data.intention_nodes,
    [nodeId]: { ...targetNode, status: 'confirming_document' },
  };
  return [{ json: {
    ...data,
    intention_nodes: intentionNodes,
    active_node_id: nodeId,
    _customization_done: false,
    message: FAILURE_MESSAGES[lang] || FAILURE_MESSAGES.es,
    error: null,
  } }];
}

if (parsed.done) {
  const intentionNodes = {
    ...data.intention_nodes,
    [nodeId]: {
      ...targetNode,
      status: targetNode._pre_confirmation_status || 'completed',
      _pending_document_lines: parsed.lines,
    },
  };
  return [{ json: { ...data, intention_nodes: intentionNodes, _customization_done: true } }];
}

const intentionNodes = {
  ...data.intention_nodes,
  [nodeId]: { ...targetNode, status: 'confirming_document', _pending_document_lines: parsed.lines },
};
return [{ json: {
  ...data,
  intention_nodes: intentionNodes,
  active_node_id: nodeId,
  _customization_done: false,
  message: parsed.message || (lang === 'en' ? 'Anything else to change?' : '¿Algo más que quieras cambiar?'),
  error: null,
} }];

// One-off CALL_FUNCTION request (see sap-inquiry-execution.json's Build Execution Prompt /
// Build SAP Payload) fetching the AFIP QR blob a SQLQueries lookup already exposes -- not
// tied to any registered intention_node (active_node_id: null), since this is
// document-generation plumbing, not a user-facing SAP operation. suppress_delivery: true
// stops sap-inquiry-execution.json's own error path from calling Execute Workflow: Response
// on a failed lookup (e.g. no AFIP QR row yet for this invoice) -- confirmed live: without
// this, a missing QR record surfaced as a raw SAP error delivered straight to the user AND
// aborted the whole document-generation run, instead of the graceful no-QR fallback Merge QR
// Result already implements (qrValue stays null when result.status !== 'success').
const data = $json;
const qrSource = data._target_document_mapping.qr_source;
const keyValue = data._target_form_state?.[qrSource.key_param];
return [{ json: {
  ...data,
  active_node_id: null,
  suppress_delivery: true,
  sap_operation: 'CALL_FUNCTION',
  sap_call_config: {
    service_name: 'SQLQueries',
    function_name: 'List',
    entity_key: qrSource.sql_name,
    params: { [qrSource.key_param]: keyValue },
  },
} }];

// Execute Workflow replaces the item wholesale (n8n nodes wipe item json) -- read the
// pre-call context back explicitly from Build QR Call Payload rather than trusting anything
// survived the hop, same convention Merge Context: Edit Invoice Lines already uses.
const before = $('Build QR Call Payload').first().json;
const result = $json;
const qrSource = before._target_document_mapping.qr_source;

// Service Layer's SQLQueries(...)/List returns an OData collection: {"value": [...]}. Each
// row's keys match the SQL's own column aliases (qr_source.sql_text's quoted identifiers).
// BLOB columns (FileContnt) come back base64-encoded in Service Layer's JSON -- convert to
// the same \x-hex convention _resolve_bucket_assets already uses for LogoImage, so
// Build Invoice Rows never needs to know which encoding a given source used.
// NOT YET LIVE-VERIFIED: confirm this exact response shape once Phase 1 (entityKey) and the
// client's own OQRC server-side whitelist are both in place.
let qrValue = null;
if (result.status === 'success') {
  const raw = result._sap_call_result;
  const rows = Array.isArray(raw?.value) ? raw.value : (Array.isArray(raw) ? raw : []);
  const cell = rows[0]?.[qrSource.target_field];
  if (typeof cell === 'string' && cell) {
    qrValue = '\\x' + Buffer.from(cell, 'base64').toString('hex');
  }
}

return [{ json: { ...before, _qr_value: qrValue } }];

// One-off CALL_FUNCTION request (see sap-inquiry-execution.json's Build Execution Prompt /
// Build SAP Payload) fetching the org's own SQLQueries-exposed company info -- not tied to
// any registered intention_node (active_node_id: null), since this is document-generation
// plumbing, not a user-facing SAP operation. suppress_delivery: true stops sap-inquiry-
// execution.json's own error path from delivering a raw SAP error to the user or aborting
// the whole document-generation run on failure -- Merge Company Info Result already falls
// back to the organization's own company_info when this comes back empty or fails, same
// convention Merge QR Result already uses for a missing QR record.
const data = $json;
const companyInfoSource = data._target_document_mapping.company_info_source;
return [{ json: {
  ...data,
  active_node_id: null,
  suppress_delivery: true,
  sap_operation: 'CALL_FUNCTION',
  sap_call_config: {
    service_name: 'SQLQueries',
    function_name: 'List',
    entity_key: companyInfoSource.sql_name,
    params: {},
  },
} }];

// Execute Workflow replaces the item wholesale (n8n nodes wipe item json) -- read the
// pre-call context back explicitly from Build Company Info Call Payload, same convention
// Merge QR Result already uses.
//
// SAP is the primary source (live, always current), but two of this subreport's fields
// can't come from SAP at all or aren't usable from it here: OADM has no website column
// (confirmed live), and this instance's own OADM.CompnyName carries a test-environment
// prefix/suffix unusable for print ("*** TEST BVS TV SA ... ****"). Each field spec
// declares an optional sap_field (tried first) and/or org_field (fallback, or the only
// source when sap_field is omitted) -- organization.company_info is a plain, non-secret
// JSON field on MOrganization (unlike integration, which is encrypted and SAP-connection-
// specific), already present on every payload via safe_to_dict().
const before = $('Build Company Info Call Payload').first().json;
const result = $json;
const spec = before._target_document_mapping.company_info_source;
const orgInfo = before.organization?.company_info || {};

let sapRow = {};
if (result.status === 'success') {
  const raw = result._sap_call_result;
  const rows = Array.isArray(raw?.value) ? raw.value : (Array.isArray(raw) ? raw : []);
  sapRow = rows[0] || {};
}

const companyInfo = { ...(spec.constants || {}) };
for (const [targetField, fieldSpec] of Object.entries(spec.fields || {})) {
  const sapValue = fieldSpec.sap_field ? sapRow[fieldSpec.sap_field] : null;
  const orgValue = fieldSpec.org_field ? orgInfo[fieldSpec.org_field] : null;
  companyInfo[targetField] = sapValue || orgValue || null;
}

// The embedded-logo picture (kind BlobField, "LogoImageEmbedded" in the template's own
// ShowEmbeddedLogo section -- confirmed live via rpt-rs's json-dump, bound to
// {OADP.LogoImage}) needs the SAME base64-encoded-then-hex convention _qr_value already
// uses, sourced entirely from the org's own company_info -- this is genuinely
// organization-wide constant data (SAP doesn't expose a company logo image at all), unlike
// company_info's other fields, which try SAP first. Written onto the MAIN row (not
// SREncabDocum's own row -- confirmed live these are two independent logo mechanisms,
// SREncabDocum.LogoImage is a separate, unrelated, intentionally-unset field).
const logoSpec = before._target_document_mapping.logo_source;
let logoValue = null;
if (logoSpec) {
  const logoBase64 = orgInfo[logoSpec.org_field];
  if (typeof logoBase64 === 'string' && logoBase64) {
    logoValue = '\\x' + Buffer.from(logoBase64, 'base64').toString('hex');
  }
}

return [{ json: { ...before, _company_info: companyInfo, _logo_value: logoValue } }];
